update public.events set facts = '[{"text": "Campeonato: Antonelli 340 pts, Russell 238, Hamilton 229 (após Singapura, 11/10)", "source": "F1.com", "url": "https://www.formula1.com/en/results/2026/drivers", "date": "2026-10-21"}, {"text": "Construtores: Mercedes lidera com 578 pts; Ferrari 444, McLaren 339", "source": "F1.com", "url": "https://www.formula1.com/en/results/2026/team", "date": "2026-10-21"}, {"text": "Gabriel Bortoleto (Audi) é o 15º, com 10 pts", "source": "F1.com", "url": "https://www.formula1.com/en/results/2026/drivers", "date": "2026-10-21"}, {"text": "Verstappen venceu as duas últimas: Bahrein (04/10) e Singapura (11/10)", "source": "F1.com", "url": "https://www.formula1.com/en/results/2026/races", "date": "2026-10-21"}, {"text": "Em Austin: Verstappen (2023), Leclerc (2024), Verstappen (2025)", "source": "F1.com", "url": "https://www.formula1.com/en/results/2025/races", "date": "2026-10-21"}, {"text": "Depois de Austin restam 5 corridas: México, Brasil, Las Vegas, Catar e Abu Dhabi", "source": "F1.com", "url": "https://www.formula1.com/en/racing/2026", "date": "2026-10-21"}]'::jsonb where id = 'f1-eua';
